def type_to_dict(typ: type) ->TypeDict:
    if is_typed_dict(typ):
        return typed_dict_to_dict(typ)
    if is_any(typ):
        return {
            'module': 'typing',
            'qualname': 'Any',
        }
    if is_generic(typ):
        qualname = qualname_of_generic(typ)
        module = typ.__module__  # type: ignore[union-attr]
        elem_types = [type_to_dict(t) for t in typ.__args__] if typ.__args__ else []  # type: ignore[union-attr]
        return {
            'module': module,
            'qualname': qualname,
            'elem_types': elem_types,
        }
    return {
        'module': typ.__module__,
        'qualname': typ.__qualname__,
    }
